## Code Example
```javascript
function createUserLoader() {
  const inFlight = new Map(); // id -> Promise
  const cache = new Map(); // id -> { data, expiry }
  const queue = [];
  const MAX_CONCURRENCY = 3;
  let active = 0;

  const fetchUser = async (id) => {
    const res = await fetch(`/api/user/${id}`);
    if (!res.ok) throw new Error('Network error');
    return res.json();
  };

  const tryStart = () => {
    while (active < MAX_CONCURRENCY && queue.length) {
      const { id, resolve, reject } = queue.shift();
      active++;
      const p = fetchUser(id)
        .then((data) => {
          cache.set(id, { data, expiry: Date.now() + 5 * 60 * 1000 });
          inFlight.delete(id);
          resolve(data);
        })
        .catch((err) => reject(err))
        .finally(() => { active--; tryStart(); });
      inFlight.set(id, p);
    }
  };

  const loadUser = (id) => {
    const cached = cache.get(id);
    if (cached && cached.expiry > Date.now()) return Promise.resolve(cached.data);
    if (inFlight.has(id)) return inFlight.get(id);
    return new Promise((resolve, reject) => {
      queue.push({ id, resolve, reject });
      tryStart();
    });
  };

  return { loadUser };
}

// Usage
// const loader = createUserLoader();
// loader.loadUser('123').then(console.log);
```

## Why This Is Asked
This question evaluates your ability to build a manifest-driven, tenant-scoped UI system with real-time data streams, dynamic component loading, and robust optimistic updates.

## Key Concepts
- useSyncExternalStore for per-tenant external data subscription
- React.lazy with dynamic widget registry for code splitting
- Manifest-driven LayoutRenderer mapping widgets to registered components
- Memoized selectors keyed by (tenantId, widgetId) for performance optimization
- Optimistic UI updates with automatic rollback on server rejection
- Proper cleanup and memory management on tenant switch

## Code Example
```javascript
// Widget Registry with lazy loading
const widgetRegistry = {
  ChartWidget: React.lazy(() => import('./widgets/ChartWidget')),
  TableWidget: React.lazy(() => import('./widgets/TableWidget')),
};

// useSyncExternalStore hook for manifest subscription
const useManifest = (tenantId) => useSyncExternalStore(
  (onStoreChange) => manifestStore.subscribe(tenantId, onStoreChange),
  () => manifestStore.getSnapshot(tenantId),
  () => manifestStore.getServerSnapshot(tenantId)
);

// Memoized selector for layout props
const useLayoutSelector = (tenantId, widgetId) => 
  useMemo(() => createSelector(tenantId, widgetId), [tenantId, widgetId]);
```

